language "moriarty/1";
agreement OracleAccumulator {
  state total: UInt = 4;
  action add(delta: UInt) {
    let updated = total + delta;
    requires updated >= total;
    next total = updated;
    ensures total >= delta;
    emit "updated"(total);
  }
}

language "moriarty/1";
agreement OracleGate {
  state ready: Bool = false;
  action set(flag: Bool) {
    requires not ready or flag;
    next ready = flag;
    ensures ready == flag;
    emit "ready"(ready);
  }
}

language "moriarty/1";
agreement OracleWrongState {
  state count: UInt = 0;
  action update() {
    next count = true;
  }
}
